"""Generate the Apps Script Calculation Result schema from the canonical JSON source."""

from __future__ import annotations

import argparse
import json
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "docs" / "stage-8-calculation-kernel" / "calculation-result.schema.json"
TARGET = ROOT / "apps-script" / "generated" / "calculation_result_schema.gs"


def render() -> str:
    schema = json.loads(SOURCE.read_text(encoding="utf-8"))
    payload = json.dumps(schema, ensure_ascii=False, indent=2, sort_keys=True)
    return (
        "/** Generated by tools/generate_calculation_result_schema.py; do not edit. */\n"
        "var CALCULATION_RESULT_SCHEMA_VERSION = 'calculation-result-v1';\n"
        f"var CALCULATION_RESULT_SCHEMA = {payload};\n"
    )


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    expected = render()
    if args.check:
        actual = TARGET.read_text(encoding="utf-8") if TARGET.exists() else ""
        if actual != expected:
            raise SystemExit("generated Calculation Result schema is stale")
        print("generated Calculation Result schema is current")
        return
    TARGET.parent.mkdir(parents=True, exist_ok=True)
    TARGET.write_text(expected, encoding="utf-8", newline="\n")


if __name__ == "__main__":
    main()
